// ---------------------------------------------------------------------
// RUN MODE. Read once, at the top, so every downstream node agrees.
//
// DRY RUN IS THE DEFAULT. Anything other than the exact string 'false'
// (case-insensitive) leaves this workflow in dry run. An unset variable, a
// typo, a variable that did not reach the container -- all of them mean
// "delete nothing". A destructive nightly job should need an explicit,
// correctly-spelled instruction to destroy, not an explicit instruction to
// hold back.
//
// n8n only exposes $env when N8N_BLOCK_ENV_ACCESS_IN_NODE=false is set on the
// container. If it is not, the reads below throw, and the catch leaves DRY_RUN
// true -- which is the safe direction.
// ---------------------------------------------------------------------
function env(key, fallback) {
  try {
    const v = $env[key];
    return (v === undefined || v === null || String(v) === '') ? fallback : String(v);
  } catch (e) {
    return fallback;   // env access blocked -> fall back, which is the safe value
  }
}

const DRY_RUN = String(env('NEXUS_PURGE_DRY_RUN', 'true')).trim().toLowerCase() !== 'false';

// Every storage path must begin with kyc/<tenant>/ before anything is deleted.
// Also default-on. See ops/destructive-scope/PROPOSED_storage_path_tenant_segment.md:
// production paths are kyc/YYYY/MM/uuid.ext today and carry NO tenant, so with
// this flag on and the paths unmigrated, every batch is abandoned and reported
// rather than deleted. That is the intended behaviour, not a bug: an
// unverifiable delete of a passport scan does not happen.
const REQUIRE_TENANT_PREFIX =
  String(env('NEXUS_PURGE_REQUIRE_TENANT_PREFIX', 'true')).trim().toLowerCase() !== 'false';

const BATCH_LIMIT = Math.max(1, Math.min(1000, parseInt(env('NEXUS_PURGE_BATCH_LIMIT', '500'), 10) || 500));
const DEDUPE_DAYS = Math.max(1, parseInt(env('NEXUS_PURGE_DEDUPE_DAYS', '7'), 10) || 7);

return [{ json: {
  DRY_RUN: DRY_RUN,
  REQUIRE_TENANT_PREFIX: REQUIRE_TENANT_PREFIX,
  BATCH_LIMIT: BATCH_LIMIT,
  DEDUPE_DAYS: DEDUPE_DAYS,
  cutoff_documents: $now.startOf('day').toUTC().toISO(),
  mode_line: (DRY_RUN ? 'DRY RUN - nothing will be deleted.' : 'LIVE - objects and rows WILL be deleted.')
             + ' Tenant prefix check: ' + (REQUIRE_TENANT_PREFIX ? 'REQUIRED' : 'DISABLED')
             + '. Batch limit ' + BATCH_LIMIT + ' per dealership. Dedupe window ' + DEDUPE_DAYS + ' days.',
} }];

// One item per dealership, explicitly. There is no "null means everyone" in
// this workflow: every read, every delete and every PATCH downstream carries a
// tenant_id, and it comes from here.
//
// The quarantine / unattributed tenant is excluded for the same reason every
// tenant-carrying view excludes it: it is not a dealership, and its rows are
// unattributed data awaiting a human decision. Purging on a schedule is not
// that decision.
const mode = $('Read Run Mode').first().json;

const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const kept = rows.filter(r => r.is_quarantine !== true && r.is_unattributed_default !== true);
const skipped = rows.filter(r => r.is_quarantine === true || r.is_unattributed_default === true);

if (kept.length === 0) {
  // Not an error, and deliberately not silent.
  return [];
}

return kept.map(t => ({ json: {
  tenant_id: t.id,
  tenant_name: t.name || t.id,
  skipped_non_dealerships: skipped.map(s => (s.name || s.id)),
  DRY_RUN: mode.DRY_RUN,
  REQUIRE_TENANT_PREFIX: mode.REQUIRE_TENANT_PREFIX,
  BATCH_LIMIT: mode.BATCH_LIMIT,
  DEDUPE_DAYS: mode.DEDUPE_DAYS,
  cutoff_documents: mode.cutoff_documents,
} }));

// Build this dealership's delete plan, and REFUSE to build one that cannot be
// proven in scope.
//
// Two independent checks, because the filter in the URL is a request and not a
// guarantee -- a typo, a PostgREST quirk or a future refactor could widen it:
//   1. every returned row's tenant_id must equal the dealership we asked for;
//   2. every storage_path must begin with 'kyc/<tenant>/'.
//
// Check 2 CANNOT PASS on production as it stands. Paths are kyc/YYYY/MM/uuid.ext
// and carry no tenant segment at all (measured 2026-09-17: 9 of 9 rows). That is
// the point: with NEXUS_PURGE_REQUIRE_TENANT_PREFIX on, this workflow abandons
// the batch and says so, rather than deleting identity documents it cannot prove
// it owns. Migrate the paths first -- see
// ops/destructive-scope/PROPOSED_storage_path_tenant_segment.md -- or set the
// flag to 'false' knowingly and accept that the delete is scoped by the database
// query alone.
const t = $('For Each Dealership').first().json;
const tenant = String(t.tenant_id);
const prefix = 'kyc/' + tenant + '/';

const rows = $input.all().map(i => i.json).filter(r => r && r.id && r.storage_path);

const foreign = rows.filter(r => String(r.tenant_id) !== tenant);
const unprefixed = rows.filter(r => !String(r.storage_path).startsWith(prefix));

const base = {
  tenant_id: tenant,
  tenant_name: t.tenant_name,
  DRY_RUN: t.DRY_RUN,
  REQUIRE_TENANT_PREFIX: t.REQUIRE_TENANT_PREFIX,
  DEDUPE_DAYS: t.DEDUPE_DAYS,
  candidates: rows.length,
  oldest_due: rows.map(r => r.retain_until).sort()[0] || null,
};

// A row belonging to another dealership in a query we scoped to this one is not
// a warning. It is a scoping failure, and nothing is deleted for anybody.
if (foreign.length) {
  return [{ json: Object.assign({}, base, {
    abandoned: true,
    abandon_reason: 'SCOPE FAILURE: ' + foreign.length + ' of ' + rows.length + ' row(s) returned by a '
      + 'query filtered to tenant_id=eq.' + tenant + ' carry a different tenant_id. Nothing was deleted '
      + 'for this dealership. Investigate before the next run.',
    pairs: [], paths: [], plan_count: 0,
  }) }];
}

if (t.REQUIRE_TENANT_PREFIX && unprefixed.length) {
  return [{ json: Object.assign({}, base, {
    abandoned: true,
    abandon_reason: 'PREFIX CHECK FAILED: ' + unprefixed.length + ' of ' + rows.length + ' storage path(s) '
      + 'do not begin with ' + prefix + ', so a bulk delete of them cannot be proven to stay inside this '
      + 'dealership. Nothing was deleted. Example: ' + String(unprefixed[0].storage_path)
      + '. This is expected until the KYC object keys are migrated to carry a tenant segment.',
    pairs: [], paths: [], plan_count: 0,
  }) }];
}

if (rows.length === 0) {
  return [{ json: Object.assign({}, base, {
    abandoned: false, abandon_reason: null, pairs: [], paths: [], plan_count: 0,
  }) }];
}

return [{ json: Object.assign({}, base, {
  abandoned: false,
  abandon_reason: null,
  plan_count: rows.length,
  ids: rows.map(r => r.id),
  paths: rows.map(r => r.storage_path),
  pairs: rows.map(r => ({ id: r.id, path: r.storage_path })),
}) }];

// DRY RUN, or a batch that was abandoned, or nothing due. Nothing was deleted.
// Emit the same shape the reconcile node emits, so one summary node serves both
// paths and the audit row reads identically apart from the verdict.
const p = $('Plan + Verify Scope').first().json;

let why;
if (p.abandoned)            why = p.abandon_reason;
else if (p.plan_count === 0) why = 'Nothing due for this dealership.';
else if (p.DRY_RUN)          why = 'DRY RUN: ' + p.plan_count + ' object(s) WOULD have been deleted for '
                                   + p.tenant_name + ' and were not. Set NEXUS_PURGE_DRY_RUN=false to arm.';
else                         why = 'Not deleted (gate closed).';

return [{ json: {
  tenant_id: p.tenant_id, tenant_name: p.tenant_name,
  dry_run: true, abandoned: !!p.abandoned,
  requested: p.plan_count || 0,
  would_delete: p.plan_count || 0,
  deleted: 0, unaccounted: 0,
  confirmed_ids: [], confirmed_paths: [],
  unaccounted_paths: (p.paths || []),
  extra_returned: [], transport_error: null, shape_unknown: false,
  oldest_due: p.oldest_due || null,
  note: why,
} }];

// Match what Storage ACTUALLY deleted against what we asked it to, for THIS
// dealership. Carried over from the original workflow, which had this right:
//
//   Supabase Storage's bulk delete returns ONLY the objects it removed. An
//   object it could not touch is simply ABSENT -- no error key, no null.
//   ABSENCE IS NOT SUCCESS. A path that does not come back is still in the
//   bucket, and its kyc_documents row must stay UNMARKED so the next run picks
//   it up again. Unmarked self-heals. Wrongly-marked does not.
const p = $('Plan + Verify Scope').first().json;
const pairs = Array.isArray(p.pairs) ? p.pairs : [];
const requested = pairs.length;
const items = $input.all().map(i => i.json || {});

const errItems = items.filter(j => j && j.error !== undefined);
let transport_error = null;
if (errItems.length) {
  const e = errItems[0].error;
  transport_error = String((e && (e.message || e.description)) || e).slice(0, 300);
}

// Normalise for COMPARISON ONLY. What we SEND is never rewritten.
const norm = s => String(s == null ? '' : s).replace(/^\/+/, '').replace(/^kyc-documents\//, '');

const returned = [];
for (const j of items) {
  if (!j || j.error !== undefined) continue;
  if (typeof j.name === 'string' && j.name.length) returned.push(j.name);
}
const returnedSet = new Set();
for (const n of returned) { returnedSet.add(n); returnedSet.add(norm(n)); }

const confirmed = [], unaccounted = [];
for (const pr of pairs) {
  const raw = String((pr && pr.path) || '');
  if (raw && (returnedSet.has(raw) || returnedSet.has(norm(raw)))) confirmed.push(pr);
  else unaccounted.push(pr);
}

const payload = items.filter(j => j && j.error === undefined && Object.keys(j).length > 0);
const shape_unknown = !transport_error && payload.length > 0 && returned.length === 0;

const requestedSet = new Set();
for (const pr of pairs) { const r = String((pr && pr.path) || ''); requestedSet.add(r); requestedSet.add(norm(r)); }
const extra_returned = returned.filter(n => !requestedSet.has(n) && !requestedSet.has(norm(n)));

// Cross-tenant paranoia, new here: anything Storage deleted that does not carry
// THIS dealership's prefix is a cross-tenant destruction and must be shouted
// about, not counted.
const prefix = 'kyc/' + String(p.tenant_id) + '/';
const foreign_deleted = returned.filter(n => !norm(n).startsWith(prefix));

return [{ json: {
  tenant_id: p.tenant_id, tenant_name: p.tenant_name,
  dry_run: false, abandoned: false,
  requested: requested, would_delete: requested,
  deleted: confirmed.length, unaccounted: unaccounted.length,
  confirmed_ids: confirmed.map(x => x.id),
  confirmed_paths: confirmed.map(x => x.path),
  unaccounted_paths: unaccounted.map(x => x.path),
  returned_count: returned.length,
  extra_returned: extra_returned,
  foreign_deleted: foreign_deleted,
  transport_error: transport_error,
  shape_unknown: shape_unknown,
  oldest_due: p.oldest_due || null,
  note: null,
} }];

// PER-DEALERSHIP SLACK ROUTING.
//
// HONEST STATE OF PLAY: there is no per-dealership Slack channel column in this
// database today. Measured 2026-09-17 - public.tenants is
// (id, slug, name, status, is_unattributed_default, is_quarantine, created_at)
// and public.tenant_configuration has no Slack field. public.channel_registry
// cannot hold it either: its channel_type CHECK constraint allows only
// 'whatsapp_waha_session' and 'whatsapp_cloud_phone_number_id'.
//
// The original workflow posted to the constant channel C0BKTLL1X54. With two
// dealerships live, that means dealership A reads alerts naming dealership B's
// compliance gaps.
//
// Until a column exists, this node does the only honest thing available: it
// still posts (losing a compliance alert is worse than misrouting one), but it
// LABELS the message with the dealership by name and says out loud that the
// channel is shared. The moment a column named slack_alert_channel_id appears
// on tenant_configuration, this node starts using it with no further change.
const t = $('For Each Dealership').first().json;
const cfgRows = $input.all().map(i => i.json).filter(r => r && !r.error);
const cfg = cfgRows[0] || {};

const configured = String(cfg.slack_alert_channel_id || '').trim();
const FALLBACK = 'C0BKTLL1X54';

const gaps = $('Find Archive Gaps (Tenant)').all()
  .map(i => i.json).filter(r => r && r.id && !r.error);

return [{ json: {
  tenant_id: t.tenant_id,
  tenant_name: t.tenant_name,
  channel_id: configured || FALLBACK,
  channel_is_shared: !configured,
  gap_count: gaps.length,
  gap_oldest: gaps.map(r => r.created_at).sort()[0] || null,
  post: gaps.length > 0,
  text: gaps.length === 0 ? '' :
    ':warning: *KYC archive gap* - *' + t.tenant_name + '*'
    + (configured ? '' : ' _(posted to the shared alert channel: no per-dealership Slack channel is '
       + 'configured for this dealership, so this alert is visible to every dealership on the shared '
       + 'channel. Add tenant_configuration.slack_alert_channel_id to fix.)_')
    + '\n' + gaps.length + ' document(s) in `kyc_documents` for this dealership have no stored file '
    + '(`storage_path IS NULL AND purged_at IS NULL`). Oldest: '
    + (gaps.map(r => r.created_at).sort()[0] || 'unknown')
    + '. The verdict was recorded but the image was never archived, so the retention record is '
    + 'incomplete for those customers.',
} }];

// One audit row per dealership. A retention policy you cannot evidence per
// dealership is not evidence for any of them: "500 documents purged" across two
// customers answers neither customer's question.
function firstOf(node, fallback) {
  try { const a = $(node).all(); return a.length ? (a[0].json || fallback) : fallback; }
  catch (e) { return fallback; }
}

// Whichever branch ran.
let r = firstOf('Reconcile (Tenant)', null);
if (!r || r.tenant_id === undefined) r = firstOf('Dry Run Report', null);
if (!r) r = { tenant_id: null, tenant_name: 'unknown', requested: 0, deleted: 0, unaccounted: 0 };

const prune = firstOf('Prune Dedupe Guard (Tenant)', null);
const slack = firstOf('Resolve Slack Channel', { gap_count: null });

const N = Number(r.requested) || 0;
const M = Number(r.deleted)   || 0;
const U = N - M;

let status;
if (r.abandoned)                            status = 'REJECTED';
else if (r.dry_run)                         status = 'DRY_RUN';
else if (r.transport_error || r.shape_unknown) status = 'FAILED';
else if (N === 0)                           status = 'SUCCESS';
else if (M === 0)                           status = 'FAILED';
else if (M === N)                           status = 'SUCCESS';
else                                        status = 'PARTIAL';

const parts = [];
parts.push('[' + (r.tenant_name || r.tenant_id) + '] Retention purge: requested ' + N
  + ', deleted ' + M + ', unaccounted ' + U
  + (r.oldest_due ? ' (oldest due ' + r.oldest_due + ')' : '') + '.');

if (r.note) parts.push(r.note);

if (U > 0 && !r.dry_run) {
  const paths = (r.unaccounted_paths || []).map(String);
  const shown = paths.slice(0, 20);
  parts.push('NOT deleted and deliberately NOT marked (still in the bucket, retried next run): '
    + shown.join(', ')
    + (paths.length > shown.length ? ' ...and ' + (paths.length - shown.length) + ' more' : '') + '.');
}
if ((r.extra_returned || []).length) {
  status = (status === 'SUCCESS') ? 'PARTIAL' : status;
  parts.push('WARNING: Storage deleted ' + r.extra_returned.length + ' object(s) that were NOT requested: '
    + r.extra_returned.slice(0, 10).join(', ') + '.');
}
if ((r.foreign_deleted || []).length) {
  status = 'FAILED';
  parts.push('CROSS-TENANT DELETION: ' + r.foreign_deleted.length + ' deleted object(s) do not carry this '
    + 'dealership prefix: ' + r.foreign_deleted.slice(0, 10).join(', ')
    + '. Stop the workflow and investigate before the next run.');
}
if (r.transport_error) parts.push('Storage delete call errored: ' + r.transport_error);
if (r.shape_unknown)   parts.push('Storage response shape unrecognised; nothing reconciled, nothing marked.');

// Dedupe prune, reported per dealership rather than as one global number.
if (prune && !prune.error) {
  const pr = Array.isArray(prune) ? prune[0] : prune;
  if (pr && pr.would_delete !== undefined) {
    parts.push('Dedupe ledger: ' + (r.dry_run
      ? (pr.would_delete + ' row(s) WOULD be pruned (dry run).')
      : (pr.deleted + ' of ' + pr.would_delete + ' row(s) pruned before ' + pr.cutoff + '.')));
  }
} else if (prune && prune.error) {
  parts.push('Dedupe prune FAILED for this dealership: '
    + String(prune.error.message || prune.error).slice(0, 200)
    + ' (is nexus_prune_processed_messages applied?).');
  if (status === 'SUCCESS') status = 'PARTIAL';
}

if (slack && slack.gap_count !== null && slack.gap_count > 0) {
  parts.push('Archive gaps for this dealership: ' + slack.gap_count
    + (slack.channel_is_shared ? ' (alert posted to the SHARED Slack channel - no per-dealership channel configured).' : '.'));
}

return [{ json: {
  workflow: 'NEXUS Retention Purge (tenant-scoped)',
  tenant_id: r.tenant_id,
  tenant_name: r.tenant_name,
  status: status,
  requested: N, deleted: M, unaccounted: U,
  summary: parts.join(' '),
} }];

// Hand this dealership's verdict back to the loop node, which will pass it and
// every earlier one to the roll-up when the last dealership is done.
const s = $('Summarise Dealership').first().json;
return [{ json: {
  tenant_id: s.tenant_id, tenant_name: s.tenant_name, status: s.status,
  requested: s.requested, deleted: s.deleted, unaccounted: s.unaccounted,
  summary: s.summary,
} }];

// Runs once, after every dealership has been through the loop. The per-dealership
// audit rows are already written by this point; this is the one-line answer to
// "what happened last night", and it must not flatten a per-dealership failure
// into an aggregate SUCCESS.
const mode = $('Read Run Mode').first().json;
const results = $input.all().map(i => i.json).filter(r => r && r.tenant_id !== undefined);

const byStatus = {};
results.forEach(r => { byStatus[r.status] = (byStatus[r.status] || 0) + 1; });

const bad = results.filter(r => r.status === 'FAILED' || r.status === 'REJECTED');
const partial = results.filter(r => r.status === 'PARTIAL');

let status;
if (results.length === 0)   status = 'NO_RESULT';
else if (bad.length)        status = 'FAILED';
else if (partial.length)    status = 'PARTIAL';
else if (results.every(r => r.status === 'DRY_RUN')) status = 'DRY_RUN';
else                        status = 'SUCCESS';

const lines = [];
lines.push(mode.mode_line);
lines.push(results.length + ' dealership(s) processed: '
  + Object.keys(byStatus).map(k => byStatus[k] + ' ' + k).join(', ') + '.');
results.forEach(r => {
  lines.push('- ' + (r.tenant_name || r.tenant_id) + ': ' + r.status
    + ' (requested ' + r.requested + ', deleted ' + r.deleted + ', unaccounted ' + r.unaccounted + ')');
});
if (bad.length) {
  lines.push('DEALERSHIPS NEEDING ATTENTION: ' + bad.map(r => r.tenant_name + ' [' + r.status + ']').join(', ')
    + '. Their per-dealership audit_log rows carry the detail.');
}

return [{ json: {
  workflow: 'NEXUS Retention Purge (tenant-scoped) - ROLL UP',
  status: status,
  tenants: results.length,
  summary: lines.join(' '),
  per_tenant: results,
} }];
